pub fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // Assumes: c is non-empty and every row is non-empty.
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
}

pub fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    assert!(!x.is_empty(), "x must have positive length");
    assert_eq!(x.len(), y.len(), "x and y must have equal length");
    assert!(!c.is_empty(), "coefficient grid c must be non-empty");
    assert!(
        c.iter().all(|row| !row.is_empty()),
        "every row in coefficient grid c must be non-empty"
    );

    let n = x.len();
    let v = default_value(&c);

    if c.len() == 1 && c[0].len() == 1 {
        vec![v; n]
    } else {
        vec![0.0; n]
    }
}